#!/usr/bin/env python3
"""Install only the reviewed website order board changes; leave data and Git HEAD intact."""
import argparse
import base64
import contextlib
import fcntl
import gzip
import hashlib
import json
import os
from pathlib import Path
import pwd
import socket
import stat
import subprocess
import tempfile
from datetime import datetime, timezone

# Regenerated from the reviewed worktree after its tests pass.
PAYLOAD = ''


def files():
    return json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))


def checked_path(root, relative):
    path = root / relative
    if Path(relative).is_absolute() or '..' in Path(relative).parts:
        raise RuntimeError('Invalid release path')
    for item in [root, *path.relative_to(root).parents]:
        candidate = root / item if not item.is_absolute() else item
        if candidate.is_symlink():
            raise RuntimeError('Symbolic path refused: ' + str(candidate))
    if path.is_symlink() or (path.exists() and not path.is_file()):
        raise RuntimeError('Unexpected release target: ' + relative)
    if not path.parent.is_dir() or path.parent.resolve() != path.parent:
        raise RuntimeError('Release parent is not a real directory: ' + relative)
    return path


def plan(root, entries):
    changes = []
    for relative, entry in entries.items():
        path = checked_path(root, relative)
        current = path.read_bytes() if path.exists() else None
        old = base64.b64decode(entry['old']) if entry['old'] is not None else None
        new = base64.b64decode(entry['new'])
        if current == new:
            continue
        if current != old:
            digest = hashlib.sha256(current).hexdigest() if current is not None else 'missing'
            raise RuntimeError('Unreviewed live change; no files replaced: ' + relative + ' sha256=' + digest)
        changes.append((relative, path, current, new))
    return changes


def atomic(path, data, uid, gid, mode):
    descriptor, temporary = tempfile.mkstemp(prefix='.website-orders-', dir=path.parent)
    try:
        with os.fdopen(descriptor, 'wb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
            os.fchown(stream.fileno(), uid, gid)
            os.fchmod(stream.fileno(), mode)
        os.replace(temporary, path)
    finally:
        with contextlib.suppress(FileNotFoundError):
            os.unlink(temporary)


def run_owner(php, root, args):
    result = subprocess.run(['runuser', '-u', 'fasakha', '--', str(php), *args],
                            cwd=root, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    if result.returncode:
        # Do not emit application exception traces or configuration/customer details.
        raise RuntimeError('Application verification failed: ' + ' '.join(args[:2]))
    return result.stdout


VERIFY = r'''<?php
require $argv[1].'/vendor/autoload.php';
$app = require $argv[1].'/bootstrap/app.php';
$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
$schema = Illuminate\Support\Facades\Schema::class;
foreach (['web_storefront_orders'=>['ticket_id','branch_id'],
    'pos_service_tickets'=>['id','branch','channel','status','payment_status','quote_snapshot','cart_snapshot','revision'],
    'branch_operation_commands'=>['branch','actor_id','request_key','request_hash','result'],
    'branch_delivery_companies'=>['id','branch','name','active']] as $table=>$columns) {
    if (!$schema::hasTable($table) || !$schema::hasColumns($table,$columns)) throw new RuntimeException('schema');
}
if (($argv[2]??'')==='installed') {
    $app->make(App\Services\Dashboard\WebsiteOrderBoardActions::class);
    foreach (['order-board.details','order-board.action','order-board.print'] as $name) {
        $route = $app['router']->getRoutes()->getByName($name);
        if (!$route || !preg_match('/^(?:'.$route->wheres['source'].')$/D','website')) throw new RuntimeException('route');
    }
}
$count = Illuminate\Support\Facades\DB::table('pos_service_tickets as t')->where('t.channel','phone')
    ->whereExists(function($query) { $query->selectRaw('1')->from('web_storefront_orders as w')
        ->whereColumn('w.ticket_id','t.id')->whereRaw("t.branch=CONCAT('f:',w.branch_id)"); })->count();
echo json_encode(['schema_ready'=>true,'website_orders'=>$count],JSON_THROW_ON_ERROR).PHP_EOL;
'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--apply', action='store_true')
    options = parser.parse_args()
    if os.geteuid() != 0 or socket.gethostname().split('.')[0] != 'srv1836524':
        raise RuntimeError('Run as root on srv1836524')
    root = Path('/home/fasakha/public_html')
    owner = pwd.getpwnam('fasakha')
    if root.is_symlink() or root.resolve() != root or root.stat().st_uid != owner.pw_uid:
        raise RuntimeError('Unexpected application root')
    php = Path('/opt/cpanel/ea-php82/root/usr/bin/php')
    if not php.is_file() or not os.access(php, os.X_OK):
        raise RuntimeError('PHP 8.2 is unavailable')
    for required in ['artisan','vendor/autoload.php','bootstrap/app.php']:
        checked_path(root, required)
    lock = Path('/run/lock/fasakhansta-website-app-orders.lock')
    with lock.open('a') as handle:
        fcntl.flock(handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
        entries = files()
        changes = plan(root, entries)
        with tempfile.TemporaryDirectory(prefix='website-orders-verify-', dir='/var/tmp') as temporary:
            temporary = Path(temporary)
            os.chmod(temporary, 0o755)
            verifier = temporary / 'verify.php'
            verifier.write_text(VERIFY)
            os.chmod(verifier, 0o644)
            before = run_owner(php, root, [str(verifier),str(root),'before'])
            for relative, _, _, new in changes:
                if relative.endswith('.php') and not relative.endswith('.blade.php'):
                    candidate = temporary / (hashlib.sha256(relative.encode()).hexdigest()+'.php')
                    candidate.write_bytes(new)
                    os.chmod(candidate, 0o644)
                    run_owner(php, root, ['-l',str(candidate)])
            if not options.apply:
                print('WEBSITE_APP_ORDERS_CHECK_OK files=' + str(len(changes)))
                print(before.strip())
                return
            backup_base = root.parent / 'website-app-orders-backups'
            if backup_base.is_symlink():
                raise RuntimeError('Unexpected backup path')
            backup_base.mkdir(mode=0o700, exist_ok=True)
            backup = Path(tempfile.mkdtemp(prefix=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ-'),dir=backup_base))
            metadata = {}
            for relative, path, old, new in changes:
                info = path.stat() if old is not None else None
                metadata[relative] = {'existed':old is not None,'uid':info.st_uid if info else owner.pw_uid,
                    'gid':info.st_gid if info else owner.pw_gid,'mode':stat.S_IMODE(info.st_mode) if info else 0o644,
                    'old_sha256':hashlib.sha256(old).hexdigest() if old is not None else None,
                    'new_sha256':hashlib.sha256(new).hexdigest()}
                if old is not None:
                    target = backup / relative
                    target.parent.mkdir(parents=True,exist_ok=True)
                    target.write_bytes(old)
            (backup/'metadata.json').write_text(json.dumps(metadata,indent=2))
            written = []
            try:
                for relative, path, old, new in changes:
                    # Repeat before each replacement: a concurrent deployment never gets overwritten.
                    checked_path(root,relative)
                    if (path.read_bytes() if path.exists() else None) != old:
                        raise RuntimeError('Concurrent source change: '+relative)
                    atomic(path,new,owner.pw_uid,owner.pw_gid,metadata[relative]['mode'])
                    written.append((relative,path,old,new))
                run_owner(php,root,['artisan','route:clear'])
                run_owner(php,root,['artisan','view:clear'])
                after = run_owner(php,root,[str(verifier),str(root),'installed'])
                (backup/'receipt.json').write_text(json.dumps({'installed':True,'files':list(entries),'verification':json.loads(after)},indent=2))
            except Exception:
                for relative,path,old,new in reversed(written):
                    if path.read_bytes() != new:
                        continue
                    if old is None:
                        path.unlink()
                    else:
                        saved = metadata[relative]
                        atomic(path,old,saved['uid'],saved['gid'],saved['mode'])
                with contextlib.suppress(Exception):
                    run_owner(php,root,['artisan','route:clear'])
                    run_owner(php,root,['artisan','view:clear'])
                raise
            print('WEBSITE_APP_ORDERS_READY files=' + str(len(changes)))
            print(after.strip())
            print('Backup: '+str(backup))


if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        print('STOPPED: '+str(error))
        raise SystemExit(1)
